# ── Metal Shading Language kernel building blocks ──
# Compose these snippets into a single `kernel void` function.
# Each snippet handles one stage. Chain them to fuse operations
# and avoid intermediate buffers.
#
# The MetalDispatch harness (above) handles device init, buffer
# wrapping, and dispatch. You only write the MSL kernel.

RESIZE_BILINEAR_MSL = '''
// Bilinear resize: sample src at fractional coords for dst pixel.
// Input: device const uchar4 *src (buffer 0)
// Output: writes to local float4 variable `pixel`
float sx = float(gid.x) * float(src_w) / float(dst_w);
float sy = float(gid.y) * float(src_h) / float(dst_h);
uint x0 = uint(sx), y0 = uint(sy);
uint x1 = min(x0+1, src_w-1), y1 = min(y0+1, src_h-1);
float fx = sx - float(x0), fy = sy - float(y0);
float4 p00 = float4(src[y0*src_w+x0]);
float4 p10 = float4(src[y0*src_w+x1]);
float4 p01 = float4(src[y1*src_w+x0]);
float4 p11 = float4(src[y1*src_w+x1]);
float4 pixel = mix(mix(p00, p10, fx), mix(p01, p11, fx), fy);
'''

BGRA_TO_RGB_FLOAT_MSL = '''
// BGRA→RGB float conversion (assumes `pixel` is float4 in BGRA order)
float r = pixel.z / 255.0f;  // R from BGRA[2]
float g = pixel.y / 255.0f;  // G from BGRA[1]
float b = pixel.x / 255.0f;  // B from BGRA[0]
'''

NORMALIZE_CHW_MSL = '''
// ImageNet normalize + write to CHW planar layout.
// mean/invstd are constant buffer floats.
// dst is device float* in CHW order: [C * H * W]
uint n = dst_w * dst_h;
uint idx = gid.y * dst_w + gid.x;
dst[0*n + idx] = (r - mean_r) * invstd_r;
dst[1*n + idx] = (g - mean_g) * invstd_g;
dst[2*n + idx] = (b - mean_b) * invstd_b;
'''

# ── Generic compute snippets (not image-specific) ──

PARALLEL_REDUCE_MSL = '''
// Parallel reduction using threadgroup shared memory.
// Works for sum, min, max — change the op on the marked line.
// Launch with: grid=(n,1,1), threadgroup=(256,1,1)
threadgroup float shared[256];
uint tid = thread_position_in_threadgroup.x;
uint gid_x = thread_position_in_grid.x;
shared[tid] = (gid_x < n) ? input[gid_x] : 0.0f;
threadgroup_barrier(mem_flags::mem_threadgroup);
for (uint s = 128; s > 0; s >>= 1) {
    if (tid < s) {
        shared[tid] += shared[tid + s];  // change to min()/max() as needed
    }
    threadgroup_barrier(mem_flags::mem_threadgroup);
}
if (tid == 0) {
    output[threadgroup_position_in_grid.x] = shared[0];
}
'''

ELEMENTWISE_FMA_MSL = '''
// Element-wise fused multiply-add: out[i] = a[i] * scale + b[i] + bias
// Generic vector math — use for normalize, scale+offset, weighted sum, etc.
// Launch with: grid=(n,1,1), threadgroup=(256,1,1)
uint i = thread_position_in_grid.x;
if (i < n) {
    out[i] = a[i] * scale + b[i] + bias;
}
'''

# ── Example: compose image snippets into a fused kernel ──
def build_resize_normalize_kernel(mean=(0.485,0.456,0.406), std=(0.229,0.224,0.225)):
    """Build a single MSL kernel that fuses resize + color convert + normalize.
    Returns MSL source string ready for MetalDispatch."""
    invstd = [1.0/s for s in std]
    return f'''
    #include <metal_stdlib>
    using namespace metal;
    kernel void fused_resize_normalize(
        device const uchar4 *src [[buffer(0)]],
        device float *dst        [[buffer(1)]],
        constant uint &src_w     [[buffer(2)]],
        constant uint &src_h     [[buffer(3)]],
        constant uint &dst_w     [[buffer(4)]],
        constant uint &dst_h     [[buffer(5)]],
        uint2 gid [[thread_position_in_grid]]
    ) {{
        if (gid.x >= dst_w || gid.y >= dst_h) return;
        {RESIZE_BILINEAR_MSL}
        {BGRA_TO_RGB_FLOAT_MSL}
        // Normalize with baked-in constants
        uint n = dst_w * dst_h;
        uint idx = gid.y * dst_w + gid.x;
        dst[0*n + idx] = (r - {mean[0]}f) * {invstd[0]}f;
        dst[1*n + idx] = (g - {mean[1]}f) * {invstd[1]}f;
        dst[2*n + idx] = (b - {mean[2]}f) * {invstd[2]}f;
    }}
    '''
